const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const action = text(input.action || 'list').toLowerCase();
const clinic_name = text(input.clinic_name);
const dead_letter_id = Number(input.dead_letter_id ?? 0);
const outbound_message_id = Number(input.outbound_message_id ?? 0);
const resolved_filter = text(input.resolved_filter || 'unresolved').toLowerCase();
const actor_name = text(input.actor_name);
const resolution_note = text(input.resolution_note);
const reset_attempts = bool(
  input.reset_attempts === undefined
    ? true
    : input.reset_attempts
);
const limit = Number(input.limit ?? 50);
const confirm_action = bool(input.confirm_action);

const actions = [
  'list',
  'get',
  'requeue',
  'resolve',
  'cancel',
  'reopen',
];

const filters = [
  'all',
  'resolved',
  'unresolved',
];

const errors = [];

if (!actions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'اقدام معتبر نیست.',
  });
}

if (
  !Number.isInteger(dead_letter_id) ||
  dead_letter_id < 0
) {
  errors.push({
    field: 'dead_letter_id',
    message: 'شناسه Dead Letter معتبر نیست.',
  });
}

if (
  !Number.isInteger(outbound_message_id) ||
  outbound_message_id < 0
) {
  errors.push({
    field: 'outbound_message_id',
    message: 'شناسه پیام معتبر نیست.',
  });
}

if (
  ['get', 'requeue', 'resolve', 'cancel', 'reopen'].includes(action) &&
  dead_letter_id < 1 &&
  outbound_message_id < 1
) {
  errors.push({
    field: 'dead_letter_reference',
    message: 'شناسه Dead Letter یا پیام الزامی است.',
  });
}

if (!filters.includes(resolved_filter)) {
  errors.push({
    field: 'resolved_filter',
    message: 'فیلتر وضعیت معتبر نیست.',
  });
}

if (
  ['requeue', 'resolve', 'cancel', 'reopen'].includes(action) &&
  !actor_name
) {
  errors.push({
    field: 'actor_name',
    message: 'نام انجام‌دهنده الزامی است.',
  });
}

if (
  ['resolve', 'cancel'].includes(action) &&
  !resolution_note
) {
  errors.push({
    field: 'resolution_note',
    message: 'توضیح نتیجه الزامی است.',
  });
}

if (
  !Number.isInteger(limit) ||
  limit < 1 ||
  limit > 500
) {
  errors.push({
    field: 'limit',
    message: 'Limit باید بین 1 و 500 باشد.',
  });
}

if (
  action !== 'list' &&
  action !== 'get' &&
  confirm_action !== true
) {
  errors.push({
    field: 'confirm_action',
    message: 'اقدام روی Dead Letter باید تأیید شود.',
  });
}

return [{
  json: {
    action,
    clinic_name,
    dead_letter_id,
    outbound_message_id,
    resolved_filter,
    actor_name,
    resolution_note,
    reset_attempts,
    limit,
    confirm_action,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
